def count_users(domain: str | None = None) -> int:
    users = store.get_all_users()
    if domain is None:
        return len(users)
    domain = domain.lower()
    count = 0
    for user in users:
        email = user["email"]
        if "@" in email:
            if email.split("@")[-1].lower() == domain:
                count += 1
    return count

